pipeline {
    agent any

    environment {
        REMOTE_HOST = '10.0.0.22' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'jenkins-server-ssh-private-key' // Jenkins中保存的远程服务器SSH凭证ID
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('Asia/Shanghai'))
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit(branches: [[name: "${params.Branch}"]], extensions: [], userRemoteConfigs: [[credentialsId: 'SSH-KEY-FOR-GITLAB', url: 'ssh://git@106.227.89.18:10093/common/liquibase.git']])
            }
        }

        stage('Mvn Compile') {
            steps {
                script {
                    sh "mvn clean deploy -Dmaven.test.skip=true -P snapshot-repo"
                }
            }
        }
    }
}
